import inspect
from typing import ForwardRef, Any, Dict
from fastapi.dependencies.utils import get_typed_return_annotation

def evaluate_forwardref(forward_ref: ForwardRef, globalns: Dict[str, Any], localns: Dict[str, Any]) -> Any:
    try:
        return forward_ref._evaluate(globalns, localns)
    except Exception as e:
        return f"Error: {e}"

def get_typed_annotation(annotation: Any, globalns: Dict[str, Any]) -> Any:
    if isinstance(annotation, str):
        annotation = ForwardRef(annotation)
        # Mocking evaluate_forwardref since I don't have the actual implementation here
        # but I can try to use the one from fastapi if I import it.
        # Actually I can just import it.
        from fastapi._compat import evaluate_forwardref
        annotation = evaluate_forwardref(annotation, globalns, globalns)
    return annotation

def get_typed_return_annotation(call):
    signature = inspect.signature(call)
    annotation = signature.return_annotation
    if annotation is inspect.Signature.empty:
        return None
    globalns = getattr(call, "__globals__", {})
    return get_typed_annotation(annotation, globalns)

def test_func() -> "None":
    return None

print(f"Return annotation: {get_typed_return_annotation(test_func)}")
